package dev.hrutvik.filesync.version;
import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.nio.charset.StandardCharsets; import java.security.*; import java.util.*;
@Service public class FileVersionService {
 private final FileVersionStore store; public FileVersionService(FileVersionStore store){this.store=store;}
 @Transactional public CommitVersionResponse commit(String tenant,CommitVersionRequest r){String path=normalize(r.path());String fp=fingerprint("PUT",r.operationId(),r.deviceId(),path,r.contentHash().toLowerCase(Locale.ROOT),r.sizeBytes(),r.baseVersion());var replay=store.replay(tenant,r.operationId(),fp);if(replay.isPresent())return replay.get();var head=store.lockHead(tenant,path);long next;UUID fileId;if(head.isEmpty()){if(r.baseVersion()!=null)throw conflict("file does not exist",null,r.baseVersion());next=1;fileId=UUID.randomUUID();}else{long current=head.get().version();if(r.baseVersion()==null||r.baseVersion()!=current)throw conflict("stale base version",current,r.baseVersion());next=current+1;fileId=head.get().fileId();}return store.save(tenant,fileId,next,new CommitVersionRequest(r.operationId(),r.deviceId(),path,r.contentHash(),r.sizeBytes(),r.baseVersion()),fp);}
 @Transactional public CommitVersionResponse delete(String tenant,String rawPath,DeleteFileRequest r){String path=normalize(rawPath.replaceFirst("^/",""));String fp=fingerprint("DELETE",r.operationId(),r.deviceId(),path,r.baseVersion());var replay=store.replay(tenant,r.operationId(),fp);if(replay.isPresent())return replay.get();var head=store.lockHead(tenant,path).orElseThrow(()->conflict("file does not exist",null,r.baseVersion()));if(head.deleted())throw conflict("file is already deleted",head.version(),r.baseVersion());if(r.baseVersion()==null||r.baseVersion()!=head.version())throw conflict("stale base version",head.version(),r.baseVersion());return store.tombstone(tenant,head,path,r,fp);}
 static String normalize(String path){String p=path.trim().replace('\\','/').replaceAll("/+","/");if(p.startsWith("/")||p.equals("..")||p.startsWith("../")||p.contains("/../")||p.endsWith("/.."))throw new IllegalArgumentException("path must be relative and cannot traverse parents");return p;}
 private static VersionConflictException conflict(String reason,Long current,Long supplied){return new VersionConflictException(reason+"; currentVersion="+current+", baseVersion="+supplied);}
 public static String fingerprint(Object... values){try{var d=MessageDigest.getInstance("SHA-256");return HexFormat.of().formatHex(d.digest(Arrays.toString(values).getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
